import{_ as a,o as e,c as n,a2 as r}from"./chunks/framework.DGzjq_gw.js";const c=JSON.parse('{"title":"精通方向扩展路线（进阶指南）","description":"","frontmatter":{},"headers":[],"relativePath":"guide/mastery.md","filePath":"guide/mastery.md","lastUpdated":1792491912000}'),o={name:"guide/mastery.md"};function i(s,t,l,d,h,g){return e(),n("div",null,[...t[0]||(t[0]=[r(`<h1 id="精通方向扩展路线-进阶指南" tabindex="-1">精通方向扩展路线（进阶指南） <a class="header-anchor" href="#精通方向扩展路线-进阶指南" aria-label="Permalink to &quot;精通方向扩展路线（进阶指南）&quot;">​</a></h1><blockquote><p>定位：本站前 10 个模块解决<strong>覆盖面</strong>（面试通过 + 日常工作够用，即 L1-L2）；本页回答「往精通走，往哪扩、按什么顺序、拿什么证明」。精通不是知识更杂，而是在少数方向上完成 L3/L4 的跃迁。</p></blockquote><h2 id="一、精通的四层阶梯" tabindex="-1">一、精通的四层阶梯 <a class="header-anchor" href="#一、精通的四层阶梯" aria-label="Permalink to &quot;一、精通的四层阶梯&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层级</th><th>标准</th><th>检验方式</th></tr></thead><tbody><tr><td><strong>L1 会用</strong></td><td>能在项目中正确使用 API 与最佳实践</td><td>完成业务需求不踩坑</td></tr><tr><td><strong>L2 懂原理</strong></td><td>能讲清&quot;为什么这样设计&quot;，答得上面试深挖</td><td>白板讲原理 10 分钟不卡壳</td></tr><tr><td><strong>L3 能实现</strong></td><td>读过源码 / 造过简化轮子，知道边界在哪</td><td>手写 mini 版本（mini-react/mini-vite）</td></tr><tr><td><strong>L4 能输出</strong></td><td>架构决策、开源影响力、带人</td><td>开源项目有真实用户 / 团队规范出自你手</td></tr></tbody></table><blockquote><p>现状定位：组件库工程化已在 L3（577 测试 + npm 发布 + CI 闭环），AI-First 方法论在 L3-L4（有流程有门禁有产出数据），其余模块大多在 L1-L2。本页的任务是选 1-2 条主线冲 L3/L4。</p></blockquote><h2 id="二、七条精通方向总览" tabindex="-1">二、七条精通方向总览 <a class="header-anchor" href="#二、七条精通方向总览" aria-label="Permalink to &quot;二、七条精通方向总览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方向</th><th>对应模块</th><th>赛道价值</th><th>简历契合度</th><th>起点</th></tr></thead><tbody><tr><td>1. 工程架构与基建</td><td><a href="/frontend-kb-pages/engineering/component-lib">组件库</a> · <a href="/frontend-kb-pages/quality/architecture-guard">架构约束</a></td><td>稀缺：会造基建的前端少</td><td><strong>最高</strong>（已有 XUI 资产）</td><td>L3</td></tr><tr><td>2. AI 前端专家</td><td><a href="/frontend-kb-pages/ai/generative-ui">Generative UI</a> · <a href="/frontend-kb-pages/ai/streaming-ui">流式渲染</a> · <a href="/frontend-kb-pages/ai/agent-rag-ui">Agent/RAG</a></td><td>最大红利：AI Native 产品井喷</td><td><strong>高</strong>（AI-First 已逐字命中 #11）</td><td>L2</td></tr><tr><td>3. 音视频专家</td><td><a href="/frontend-kb-pages/network/webrtc">WebRTC</a> · <a href="/frontend-kb-pages/network/media">媒体专项</a></td><td>高溢价：音视频前端长期稀缺</td><td>中（有 ffmpeg/WebSocket 桥接）</td><td>L1</td></tr><tr><td>4. 性能专家</td><td><a href="/frontend-kb-pages/performance/loading">加载</a> · <a href="/frontend-kb-pages/performance/rendering">渲染</a></td><td>稳定刚需，与监控/大屏联动</td><td>中高（大屏/适配实战）</td><td>L2</td></tr><tr><td>5. 框架原理</td><td><a href="/frontend-kb-pages/framework/react">React</a> · <a href="/frontend-kb-pages/framework/vue">Vue</a> · <a href="/frontend-kb-pages/basics/js-core">JS 核心</a></td><td>面试硬通货，全岗位通用</td><td>高（双栈 + 响应式原理已有）</td><td>L2</td></tr><tr><td>6. 可视化/图形学</td><td><a href="/frontend-kb-pages/visualization/echarts">ECharts</a> · <a href="/frontend-kb-pages/visualization/map-3d">地图三维</a></td><td>偏门但大屏/数字孪生需求稳</td><td>中（fabric.js + Three.js 接触）</td><td>L1-L2</td></tr><tr><td>7. Node 全栈</td><td><a href="/frontend-kb-pages/backend/nodejs">Node</a> · <a href="/frontend-kb-pages/backend/nestjs">Nest</a> · <a href="/frontend-kb-pages/backend/database-bff">BFF</a></td><td>全栈溢价，BFF/工具链入口</td><td>中（了解级）</td><td>L1</td></tr></tbody></table><h2 id="三、逐方向展开-现状-→-补什么-→-里程碑" tabindex="-1">三、逐方向展开：现状 → 补什么 → 里程碑 <a class="header-anchor" href="#三、逐方向展开-现状-→-补什么-→-里程碑" aria-label="Permalink to &quot;三、逐方向展开：现状 → 补什么 → 里程碑&quot;">​</a></h2><h3 id="方向-1-工程架构与基建-推荐主线-起点最高" tabindex="-1">方向 1：工程架构与基建（推荐主线，起点最高） <a class="header-anchor" href="#方向-1-工程架构与基建-推荐主线-起点最高" aria-label="Permalink to &quot;方向 1：工程架构与基建（推荐主线，起点最高）&quot;">​</a></h3><ul><li><strong>现状</strong>：XUI 组件库已具备契约驱动架构、monorepo、changesets、CI 全自动——这是多数 5 年经验的前端都没有的完整闭环。</li><li><strong>精通补强</strong>： <ul><li>主题系统进阶：Design Token 三层体系（全局 → 组件 → 实例）、暗色主题的语义化变量设计；</li><li>无障碍（a11y）与键盘导航：WAI-ARIA 模式库（combobox/dialog/menu 的完整键盘交互）；</li><li>SSR/RSC 兼容与 <code>use client</code> 边界设计；包体积治理（tree-shaking 验证、sideEffects、按需加载矩阵）；</li><li>微前端与模块联邦：多团队共用基建时的版本隔离与样式隔离方案；</li><li>AST 与代码修改：Babel/ESLint 自定义规则（把架构约束写成工具，而非口头规范）。</li></ul></li><li><strong>里程碑产出</strong>：XUI 升级 v1.0——补 a11y 审计报告 + SSR 兼容 + bundle 治理看板；写 1 篇《契约驱动双端组件库》长文。</li><li><strong>精通检验</strong>：能否手写一个 mini-vitest？能否讲清 changesets 为什么优于 lerna？能否用 ESLint 自定义规则实现&quot;禁止跨层 import&quot;？</li></ul><h3 id="方向-2-ai-前端专家-推荐主线-赛道红利最大" tabindex="-1">方向 2：AI 前端专家（推荐主线，赛道红利最大） <a class="header-anchor" href="#方向-2-ai-前端专家-推荐主线-赛道红利最大" aria-label="Permalink to &quot;方向 2：AI 前端专家（推荐主线，赛道红利最大）&quot;">​</a></h3><ul><li><strong>现状</strong>：流式渲染有实战（AI 客服），AI-First 方法论完整，GenUI/Agent/RAG 停在概念级（L2 不到）。</li><li><strong>精通补强</strong>： <ul><li>GenUI 从概念到实现：自建组件注册表 + 流式 JSON 解析 + 骨架二段渲染 demo（本站 <a href="/frontend-kb-pages/ai/generative-ui">Generative UI</a> 页的示例扩展成真实项目）；</li><li>Agent 前端编排：工具调用可视化（调用树/重试/并行）、多 Agent 状态机、human-in-the-loop 确认流；</li><li>本地推理：WebGPU + WebLLM 跑通 1 个浏览器内小模型，理解量化与显存约束；</li><li>协议层：MCP（Model Context Protocol）前端接入、OpenAI Realtime API 语音链路；</li><li>RAG 界面工程化：引用溯源、相关性反馈、分块可视化调试界面。</li></ul></li><li><strong>里程碑产出</strong>：开源一个「AI Chat 前端最佳实践」项目（流式 + GenUI + 工具调用可视化三合一），对标 vercel/ai 的 React 生态但补 Vue 侧空缺——Vue 生态的 AI UI 库几乎空白，是差异化机会。</li><li><strong>精通检验</strong>：能否讲清 SSE 流式中断恢复的完整方案？能否设计一个 Agent 工具调用的前端状态机？</li></ul><h3 id="方向-3-音视频专家-若投-11-8-1-则临时升为主攻" tabindex="-1">方向 3：音视频专家（若投 #11/#8/#1 则临时升为主攻） <a class="header-anchor" href="#方向-3-音视频专家-若投-11-8-1-则临时升为主攻" aria-label="Permalink to &quot;方向 3：音视频专家（若投 #11/#8/#1 则临时升为主攻）&quot;">​</a></h3><ul><li><strong>现状</strong>：ffmpeg 操作实战 + WebSocket 推送，WebRTC/MSE 概念级（L1）。</li><li><strong>精通补强</strong>：WebRTC 完整链路实操（信令服务器手写 → 双人通话 demo → SFU 概念）；WebCodecs 帧级编解码；播放器自研（MSE + hls.js 源码阅读）；音频处理（Web Audio 图 + AudioWorklet）。</li><li><strong>里程碑产出</strong>：浏览器双人通话 demo（自写信令）+ 一个 MSE 直播播放器 demo。</li><li><strong>精通检验</strong>：能否讲清 ICE 穿透全过程？能否解释卡顿率与丢包率的统计口径？</li></ul><h3 id="方向-4-性能专家" tabindex="-1">方向 4：性能专家 <a class="header-anchor" href="#方向-4-性能专家" aria-label="Permalink to &quot;方向 4：性能专家&quot;">​</a></h3><ul><li><strong>精通补强</strong>：性能监控 SDK 完整实现（<a href="/frontend-kb-pages/performance/loading">监控三件套</a>扩展为真实上报 + 看板）；Chrome 性能面板深度（Performance/Performance/Memory 三面板熟练）；渲染管线级理解（合成层提升、paint flashing、GPU 栅格化）；Web Vitals 全指标优化手册（INP 是新重点）。</li><li><strong>里程碑产出</strong>：性能 SDK 开源（异常 + 性能 + 埋点 + sourcemap 还原），配一个真实站点的优化前后对比报告。</li><li><strong>精通检验</strong>：给定一个卡顿页面，能否 30 分钟内定位到主因？</li></ul><h3 id="方向-5-框架原理-面试刚需-投入产出比最高" tabindex="-1">方向 5：框架原理（面试刚需，投入产出比最高） <a class="header-anchor" href="#方向-5-框架原理-面试刚需-投入产出比最高" aria-label="Permalink to &quot;方向 5：框架原理（面试刚需，投入产出比最高）&quot;">​</a></h3><ul><li><strong>精通补强</strong>：手写 mini-react（Fiber 遍历 + useState 闭包 + diff）；手写 mini-vue 响应式（Proxy 依赖收集 + 调度器）；Vue 编译器管线（template → AST → transform → generate）；React 并发调度（lane 模型、可中断渲染）。</li><li><strong>里程碑产出</strong>：两个 mini 仓库挂 GitHub，配博客长文——这是面试&quot;深入理解 React 核心原理&quot;（#11 原话）的最硬证明。</li><li><strong>精通检验</strong>：面试问&quot;useState 闭包陷阱&quot;&quot;为何 Vue 不需要 key 反查&quot;时能否到源码层回答。</li></ul><h3 id="方向-6-可视化-图形学" tabindex="-1">方向 6：可视化/图形学 <a class="header-anchor" href="#方向-6-可视化-图形学" aria-label="Permalink to &quot;方向 6：可视化/图形学&quot;">​</a></h3><ul><li><strong>精通补强</strong>：ECharts 源码级（zrender 渲染层、大数据量的 LTTB 降采样）；WebGL 基础（矩阵变换、着色器 GLSL 入门、手写三角形）；D3 数据 join 思想（图形语法理论）。</li><li><strong>里程碑产出</strong>：手写 WebGL 渲染 10 万点散点图（对比 ECharts large 模式），一篇《Canvas 性能天花板在哪》。</li></ul><h3 id="方向-7-node-全栈" tabindex="-1">方向 7：Node 全栈 <a class="header-anchor" href="#方向-7-node-全栈" aria-label="Permalink to &quot;方向 7：Node 全栈&quot;">​</a></h3><ul><li><strong>精通补强</strong>：libuv 与事件循环（与浏览器差异）；Stream 背压；Nest.js 依赖注入原理；数据库索引与慢查询；Dockerfile 多阶段构建前端应用。</li><li><strong>里程碑产出</strong>：XUI 文档站加一个真实 BFF（评论/统计接口）上线，走通 PM2/Docker 部署。</li></ul><h2 id="四、按画像的推荐主攻组合" tabindex="-1">四、按画像的推荐主攻组合 <a class="header-anchor" href="#四、按画像的推荐主攻组合" aria-label="Permalink to &quot;四、按画像的推荐主攻组合&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>主线（默认）：方向 1 工程架构 + 方向 2 AI 前端</span></span>
<span class="line"><span>理由：完全复用已有资产（XUI + AI-First），符合 #9/#11 的画像，</span></span>
<span class="line"><span>     且&quot;组件库作者 + AI 前端实践者&quot;是当前市场最稀缺的组合。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>辅线（穿插进行）：方向 5 框架原理</span></span>
<span class="line"><span>理由：面试硬通货，mini-react/mini-vue 两个仓库即可，投入 2-3 周一次性变现。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>按岗切换：投音视频岗（#11/#8/#1）→ 方向 3 临时升为主攻</span></span>
<span class="line"><span>        投大屏/监控岗（#7/#3）→ 方向 4 临时升为主攻</span></span></code></pre></div><h2 id="五、节奏与检验" tabindex="-1">五、节奏与检验 <a class="header-anchor" href="#五、节奏与检验" aria-label="Permalink to &quot;五、节奏与检验&quot;">​</a></h2><ol><li><strong>两周一个里程碑</strong>：每方向拆成可交付的小产出（demo/仓库/长文），避免&quot;学了但没证据&quot;；</li><li><strong>L3 的统一检验法</strong>：给该方向写一个 mini 实现——写不出即说明还停在 L2；</li><li><strong>L4 的统一检验法</strong>：该方向的产出是否有陌生人的 Star/Issue/使用——没有就继续做减法打磨；</li><li><strong>与求职的关系</strong>：本站模块页保证&quot;面得过&quot;，本页的主线保证&quot;谈得深&quot;——面试终面与定级差异，就在 L3/L4 的证据上。</li></ol><h2 id="面试要点" tabindex="-1">面试要点 <a class="header-anchor" href="#面试要点" aria-label="Permalink to &quot;面试要点&quot;">​</a></h2><ol><li><strong>&quot;精通&quot;怎么证明而不是口头？</strong> 三件套：开源产出（mini 轮子/组件库）+ 源码级回答 + 量化战绩，本页每方向的&quot;里程碑产出&quot;就是为此设计。</li><li><strong>为什么选工程架构 + AI 前端做主线？</strong> 资产复用最大化（已有 XUI 与 AI-First 方法论）、赛道红利（AI Native 井喷）、市场稀缺（Vue 生态 AI UI 库空白）。</li><li><strong>面到源码答不上怎么办？</strong> 承认边界 + 给方法论：&quot;这个细节我没读到那一层，但按 xx 的架构推测应该是 yy，我会回去验证&quot;——比硬编可信。</li><li><strong>精通与广度矛盾吗？</strong> 用&quot;一专多能&quot;回答：本站 10 模块是多能（L1-L2 保底），1-2 条主线是一专（L3/L4 定级），招聘要的正是这个组合。</li></ol>`,28)])])}const p=a(o,[["render",i]]);export{c as __pageData,p as default};
